//! Which converted file serves which cores, per kernel. Generated by
//! `tools/blas_asm/gen.zig`; re-derive it rather than editing it.

const std = @import("std");

pub const Entry = struct {
    role: []const u8,
    /// Empty when the file is the same however the source is built.
    variant: []const u8,
    cores: []const []const u8,
    module: type,
};

pub const entries = [_]Entry{
    .{ .role = "ddot", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("ddot_32.zig") },
    .{ .role = "ddot", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("ddot_64.zig") },
    .{ .role = "sdot", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("sdot_32.zig") },
    .{ .role = "sdot", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("sdot_64.zig") },
    .{ .role = "zdotu", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("zdotu_32.zig") },
    .{ .role = "zdotu", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("zdotu_64.zig") },
    .{ .role = "zdotc", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("zdotc_32.zig") },
    .{ .role = "zdotc", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("zdotc_64.zig") },
    .{ .role = "cdotu", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("cdotu_32.zig") },
    .{ .role = "cdotu", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("cdotu_64.zig") },
    .{ .role = "cdotc", .variant = "32", .cores = &.{
        "sparcv7",
    }, .module = @import("cdotc_32.zig") },
    .{ .role = "cdotc", .variant = "64", .cores = &.{
        "sparcv7",
    }, .module = @import("cdotc_64.zig") },
};

/// The file whose function `role` is, for `core` built as `variant`, if it
/// is assembly there.
pub fn source(comptime role: []const u8, comptime core: []const u8, comptime variant: []const u8) ?type {
    @setEvalBranchQuota(1_000_000);
    inline for (entries) |e| {
        if (comptime std.mem.eql(u8, e.role, role) and (e.variant.len == 0 or std.mem.eql(u8, e.variant, variant))) {
            inline for (e.cores) |c| {
                if (comptime std.mem.eql(u8, c, core)) return e.module;
            }
        }
    }
    return null;
}
